update meqyro.question_translations set prompt='Which figure comes next? Consider the odd and even positions separately.' where question_id=qid and locale='en';
update meqyro.question_translations set prompt='¿Qué figura viene a continuación? Observa por separado las posiciones impares y pares.' where question_id=qid and locale='es';
update meqyro.question_translations set prompt='Quelle figure vient ensuite ? Examinez séparément les positions impaires et paires.' where question_id=qid and locale='fr';
